// TH18 v1.00a Stage 3 wave 04: st03.ecl.txt:1142-1180 (MainSub03).
// 88 GirlBlueA02/GirlRedA02: 6x(2 pairs,40f), 10x(2 pairs,30f), 6x(2 pairs,10f).
// Runtime closure: S:568-575 (GirlBlueA02), S:918-925 (GirlRedA02), S:189-289
// (GirlA02 / GirlA02_at). Parent is stage main at (0,0); no prior boss state.

const TIME_LIMIT: int = 1900; // 120f shell buffer + 1280f schedule + last volley/tail
const TH18_RICE: int = 480;   // type 8 Rice, base radius 2.4

// S:225/S:236/S:253/S:264: VELTIME 30f to 0.01 along the current angle, WAIT 120,
// then VELTIME 30f to the rank target and re-aim at the player at effect entry.
// S:224/S:252 type2/ANIM a=1 is omitted; its 4*2.2px retreat is kept with sh_dist.
xformdef FREEZE_REAIM(target: fx) {
    step_speed(0.01fx, 30 + 65536 * EASE_LINEAR);
    wait(30);
    wait(120);
    aim_player(0deg);
    step_speed(target, 30 + 65536 * EASE_LINEAR);
}

// S:205-288 GirlA02_at. Two et slots. Slots are per-task, so configure both here.
async sub girl_a02_fire(ts0: fx, ts1: fx) {
    var rank: int = global(GVAR_RANK);
    var n1: int = 6;
    var interval: int = 60;
    if rank == 2 {
        interval = 40;
    } else if rank == 3 {
        n1 = 14;        // S:246-248 etCount slot1
        interval = 30;
    }

    wait(10 + rand(100)); // S:208 wait(10 + ($RAND % 100))

    // S:209-226 slot 0: etAim 3, fixed 6-way ring.
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 6);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, 6, 1);
    sh_angle(0, 0deg, 0deg);
    sh_speed(0, 2.2fx, 0fx);
    sh_dist(0, -8.8fx);
    sh_xform(0, FREEZE_REAIM(ts0));

    // S:237-264 slot 1: etAim 5, fixed half-offset ring, 6 or 14 ways.
    sh_reset(1);
    sh_sprite(1, TH18_RICE, 6);
    sh_aim(1, 0);
    sh_ring(1, 1);
    sh_count(1, n1, 1);
    sh_speed(1, 2.2fx, 0fx);
    sh_dist(1, -8.8fx);
    sh_xform(1, FREEZE_REAIM(ts1));

    // S:266-286: $B=2, random ring base before each volley; E skips slot0.
    for volley in 0..2 {
        var base: angle = rand(65536) as angle;
        sh_angle(0, base, 0deg);
        sh_angle(1, base + (32768 / n1) as angle, 0deg);
        if rank != 0 {
            sh_fire(0); // S:271-273 !NHL etOn(0)
        }
        sh_fire(1);     // S:274 etOn(1)
        wait(interval);
    }
}

// S:189-203 GirlA02 main. enmCreateM gives the right-hand child mirror=1;
// movement angles reflect as 180deg-angle (enemy-state.md §2-3).
async sub girl_a02(mirror: int, ts0: fx, ts1: fx) {
    set_invuln(65535);
    set_hurtbox(12fx); // S:191 setHurtbox(24,24) -> source radius 12
    set_hitbox(8fx);   // S:192 setHitbox(16,16) -> source radius 8

    var start: angle = 0deg;
    if mirror != 0 {
        start = 180deg;
    }
    move_vel(0, start, 2fx, EASE_LINEAR); // S:193 moveVel(0,2.0)
    spawn girl_a02_fire(ts0, ts1);        // S:194 @GirlA02_at() async

    wait(60); // S:195
    var turn: angle = rand(8192) as angle; // S:196 0 + RANDF*pi/4
    var target: angle = turn;
    if mirror != 0 {
        target = 180deg - turn;
    }
    move_vel(120, target, 2fx, EASE_QUAD_IN); // S:196 mode1
    loop { wait(1000); } // S:197-202 off-screen recycle
}

// S:1142-1180 MainSub03. Source parent is the stage main; absolute spawn coords.
async sub wave_pattern() {
    wait(120); // practice-shell opening buffer

    var rank: int = global(GVAR_RANK);
    var ts0: fx = 2fx;
    var ts1: fx = 2.5fx;
    if rank == 2 {
        ts0 = 2.5fx;
        ts1 = 3fx;
    } else if rank == 3 {
        ts0 = 2.6fx;
        ts1 = 3fx;
    }

    var i: int = 0;
    var y1: fx = 0fx;
    var y2: fx = 0fx;

    // S:1145-1156: six rounds, each with two pairs and 40f after each pair.
    while i < 6 {
        y1 = 64fx + (rand(8192) as fx) / 64fx;
        y2 = 64fx + (rand(8192) as fx) / 64fx;
        _ = spawn_enemy(-224fx, y1, 180, 0, 0, 0, girl_a02(0, ts0, ts1));
        _ = spawn_enemy(224fx, y2, 180, 0, 0, 0, girl_a02(1, ts0, ts1));
        wait(40);
        y1 = 64fx + (rand(8192) as fx) / 64fx;
        y2 = 64fx + (rand(8192) as fx) / 64fx;
        _ = spawn_enemy(-224fx, y1, 180, 0, 0, 0, girl_a02(0, ts0, ts1));
        _ = spawn_enemy(224fx, y2, 180, 0, 0, 0, girl_a02(1, ts0, ts1));
        wait(40);
        i = i + 1;
    }

    wait(80); // S:1156

    // S:1157-1167: ten rounds, two pairs, 30f after each pair.
    i = 0;
    while i < 10 {
        y1 = 64fx + (rand(8192) as fx) / 64fx;
        y2 = 64fx + (rand(8192) as fx) / 64fx;
        _ = spawn_enemy(-224fx, y1, 160, 0, 0, 0, girl_a02(0, ts0, ts1));
        _ = spawn_enemy(224fx, y2, 160, 0, 0, 0, girl_a02(1, ts0, ts1));
        wait(30);
        y1 = 64fx + (rand(8192) as fx) / 64fx;
        y2 = 64fx + (rand(8192) as fx) / 64fx;
        _ = spawn_enemy(-224fx, y1, 160, 0, 0, 0, girl_a02(0, ts0, ts1));
        _ = spawn_enemy(224fx, y2, 160, 0, 0, 0, girl_a02(1, ts0, ts1));
        wait(30);
        i = i + 1;
    }

    // S:1168-1178: six rounds, two pairs, 10f after each pair.
    i = 0;
    while i < 6 {
        y1 = 64fx + (rand(8192) as fx) / 64fx;
        y2 = 64fx + (rand(8192) as fx) / 64fx;
        _ = spawn_enemy(-224fx, y1, 110, 0, 0, 0, girl_a02(0, ts0, ts1));
        _ = spawn_enemy(224fx, y2, 110, 0, 0, 0, girl_a02(1, ts0, ts1));
        wait(10);
        y1 = 64fx + (rand(8192) as fx) / 64fx;
        y2 = 64fx + (rand(8192) as fx) / 64fx;
        _ = spawn_enemy(-224fx, y1, 110, 0, 0, 0, girl_a02(0, ts0, ts1));
        _ = spawn_enemy(224fx, y2, 110, 0, 0, 0, girl_a02(1, ts0, ts1));
        wait(10);
        i = i + 1;
    }

    loop { wait(60); }
}

// Existing invincible practice shell: control enemy at (0,0), no body collision.
async sub wave_control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_hitbox(0fx);
    set_hurtbox(0fx);
    phase_begin(0, wave_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, wave_control);
    loop { wait(600); }
}
